queries.query:
find view "view:sto:all_baseline_issue_summary" a
| join view "view:sto:hierarchy_lookup" h_l on h_l.parent_unique_id = a.parent_unique_id and h_l.account_identifier = a.account_identifier
| left join view "view:sto:account_product" p on p.id = a.product_id and p.account_identifier = a.account_identifier
| filter a.status = "Active"
and a.last_modified >= cast(${start_time} as timestamp) and a.last_modified <= cast(${end_time} as timestamp)
and ${org_filter_predicate}
and ${project_filter_predicate}
and ${scanner_filter_predicate}
and ${severity_filter_predicate}
and ${exempted_filter_predicate}
and (a.severity_code = "Critical" or a.severity_code = "High")
| select { distinct_count(a.issue_id) as active_critical_high }
| limit 1

find view "view:sto:latest_baseline_scan" l
| join view "view:sto:scan" s on s.internal_id = l.scan_internal_id
| join view "view:sto:hierarchy_lookup" h_l on h_l.parent_unique_id = l.parent_unique_id and h_l.account_identifier = l.account_identifier
| left join view "view:sto:account_product" p on p.id = l.product_id and p.account_identifier = l.account_identifier
| join view "view:sto:target" t on t.id = l.target_id
| filter t.is_deleted = false
and s.created >= cast(${start_time} as timestamp) and s.created <= cast(${end_time} as timestamp)
and ${org_filter_predicate}
and ${project_filter_predicate}
and ${target_filter_predicate}
and ${ttype_filter_predicate}
and ${scanner_filter_predicate}
and ${pipeline_filter_predicate}
and (l.critical + l.high + l.medium + l.low) > 0
| select { distinct_count(l.target_id) as vulnerable_targets }
| limit 1

find view "view:sto:scan" s
| join view "view:sto:hierarchy_lookup" h_l on h_l.parent_unique_id = s.parent_unique_id and h_l.account_identifier = s.account_identifier
| left join view "view:sto:account_product" p on p.id = s.product_id and p.account_identifier = s.account_identifier
| left join view "view:sto:target_variant" tv on tv.id = s.target_variant_id
| left join view "view:sto:target" t on t.id = tv.target_id
| filter s.is_deleted = false
and s.created >= cast(${start_time} as timestamp) and s.created <= cast(${end_time} as timestamp)
and ${org_filter_predicate}
and ${project_filter_predicate}
and ${target_filter_predicate}
and ${ttype_filter_predicate}
and ${scanner_filter_predicate}
and ${pipeline_filter_predicate}
| select { count() as scans_run }
| limit 1

find view "view:sto:detection" d
| join view "view:sto:hierarchy_lookup" h_l on h_l.parent_unique_id = d.parent_unique_id and h_l.account_identifier = d.account_identifier
| left join view "view:sto:account_product" p on p.id = d.product_id and p.account_identifier = d.account_identifier
| left join view "view:sto:target" t on t.id = d.target_id
| filter d.is_baseline = true
and ${org_filter_predicate}
and ${project_filter_predicate}
and ${target_filter_predicate}
and ${ttype_filter_predicate}
and ${scanner_filter_predicate}
and ${pipeline_filter_predicate}
and ${severity_filter_predicate}
and ${exempted_filter_predicate}
and d.remediated is null
and d.last_scanned >= cast(${start_time} as timestamp) and d.last_scanned <= cast(${end_time} as timestamp)
and (d.severity_code = "Critical" or d.severity_code = "High")
| select { avg(date_diff(d.detected, now(), "second")) as mean_time_open }
| limit 1

with scanned as (
find view "view:sto:scan" s
| join view "view:sto:target_variant" tv on tv.id = s.target_variant_id
| filter s.is_deleted = false
and s.created >= cast(${start_time} as timestamp) and s.created <= cast(${end_time} as timestamp)
| select { tv.target_id as target_id, count() as scans, max(s.created) as last_scan }
| group_by tv.target_id
)
find view "view:sto:target" t
| join view "view:sto:hierarchy_lookup" h_l on h_l.parent_unique_id = t.parent_unique_id and h_l.account_identifier = t.account_identifier
| left join scanned sc on sc.target_id = t.id
| filter t.is_deleted = false
and t.created <= cast(${end_time} as timestamp)
and ${org_filter_predicate}
and ${project_filter_predicate}
and ${target_filter_predicate}
and ${ttype_filter_predicate}
| select { round(count(sc.target_id) * 100.0 / count(), 1) as scan_coverage_pct }
| limit 1

find view "view:sto:scan" s
| join view "view:sto:hierarchy_lookup" h_l on h_l.parent_unique_id = s.parent_unique_id and h_l.account_identifier = s.account_identifier
| left join view "view:sto:account_product" p on p.id = s.product_id and p.account_identifier = s.account_identifier
| left join view "view:sto:target_variant" tv on tv.id = s.target_variant_id
| left join view "view:sto:target" t on t.id = tv.target_id
| filter s.is_deleted = false
and s.created >= cast(${start_time} as timestamp) and s.created <= cast(${end_time} as timestamp)
and ${org_filter_predicate}
and ${project_filter_predicate}
and ${target_filter_predicate}
and ${ttype_filter_predicate}
and ${scanner_filter_predicate}
and ${pipeline_filter_predicate}
and s.status != "Running"
| select { round(sum(case when s.status = "Succeeded" then 1 else 0 end) * 100.0 / count(), 1) as scan_success_pct }
| limit 1

find view "view:sto:all_baseline_issue_summary" a
| join view "view:sto:hierarchy_lookup" h_l on h_l.parent_unique_id = a.parent_unique_id and h_l.account_identifier = a.account_identifier
| left join view "view:sto:account_product" p on p.id = a.product_id and p.account_identifier = a.account_identifier
| filter a.status = "Active"
and a.last_modified >= cast(${start_time} as timestamp) and a.last_modified <= cast(${end_time} as timestamp)
and ${org_filter_predicate}
and ${project_filter_predicate}
and ${scanner_filter_predicate}
and ${severity_filter_predicate}
and ${exempted_filter_predicate}
| select { round(sum(case when a.severity_code = "Critical" or a.severity_code = "High" then 1 else 0 end) * 100.0 / count(), 1) as critical_high_pct }
| limit 1

with scanned_exec as (
find view "view:sto:scan" s
| filter s.is_deleted = false and s.created >= cast(${start_time} as timestamp) and s.created <= cast(${end_time} as timestamp)
| select { s.plan_execution_id as pe_id }
| group_by s.plan_execution_id
)
find view "ci:pipeline_execution_summary_ci" c
| left join scanned_exec se on se.pe_id = c.planexecutionid
| filter c.startts_date >= cast(${start_time} as timestamp) and c.startts_date <= cast(${end_time} as timestamp)
and ${org_filter_predicate}
and ${project_filter_predicate}
and ${pipeline_filter_predicate}
| select { round(count(se.pe_id) * 100.0 / count(), 1) as scanned_build_pct }
| limit 1

find view "view:sto:daily_baseline_scan" b
| join view "view:sto:hierarchy_lookup" h_l on h_l.parent_unique_id = b.parent_unique_id and h_l.account_identifier = b.account_identifier
| left join view "view:sto:account_product" p on p.id = b.product_id and p.account_identifier = b.account_identifier
| left join view "view:sto:target" t on t.id = b.target_id
| filter b.day >= cast(${start_time} as timestamp) and b.day <= cast(${end_time} as timestamp)
and ${org_filter_predicate}
and ${project_filter_predicate}
and ${target_filter_predicate}
and ${ttype_filter_predicate}
and ${scanner_filter_predicate}
| select {
b.day as scan_day,
sum(b.critical + b.high + b.medium + b.low) as open_findings,
sum(b.critical * 16 + b.high * 7 + b.medium * 2) as risk_score
}
| group_by b.day
| order_by scan_day asc
| limit 500

find view "view:sto:all_baseline_issue_summary" a
| join view "view:sto:hierarchy_lookup" h_l on h_l.parent_unique_id = a.parent_unique_id and h_l.account_identifier = a.account_identifier
| left join view "view:sto:account_product" p on p.id = a.product_id and p.account_identifier = a.account_identifier
| filter a.status = "Active"
and a.last_modified >= cast(${start_time} as timestamp) and a.last_modified <= cast(${end_time} as timestamp)
and ${org_filter_predicate}
and ${project_filter_predicate}
and ${scanner_filter_predicate}
and ${severity_filter_predicate}
and ${exempted_filter_predicate}
| select {
(case
when a.severity_code = "Critical" then 5
when a.severity_code = "High" then 4
when a.severity_code = "Medium" then 3
when a.severity_code = "Low" then 2
when a.severity_code = "Info" then 1
else 0
end) as severity_order,
a.severity_code as severity,
distinct_count(a.issue_id) as active_issues
}
| group_by severity_order, a.severity_code
| order_by severity_order desc
| limit 10

with wk_scans as (
find view "view:sto:scan" s
| join view "view:sto:hierarchy_lookup" h_l on h_l.parent_unique_id = s.parent_unique_id and h_l.account_identifier = s.account_identifier
| left join view "view:sto:account_product" p on p.id = s.product_id and p.account_identifier = s.account_identifier
| left join view "view:sto:target_variant" tv on tv.id = s.target_variant_id
| left join view "view:sto:target" t on t.id = tv.target_id
| filter s.is_deleted = false
and s.created >= cast(${start_time} as timestamp) and s.created <= cast(${end_time} as timestamp)
and ${org_filter_predicate}
and ${project_filter_predicate}
and ${target_filter_predicate}
and ${ttype_filter_predicate}
and ${scanner_filter_predicate}
and ${pipeline_filter_predicate}
| select { date_trunc("week", s.created) as wk, count() as scans }
| group_by wk
),
wk_det as (
find view "view:sto:detection" d
| join view "view:sto:hierarchy_lookup" h_l on h_l.parent_unique_id = d.parent_unique_id and h_l.account_identifier = d.account_identifier
| left join view "view:sto:account_product" p on p.id = d.product_id and p.account_identifier = d.account_identifier
| left join view "view:sto:target" t on t.id = d.target_id
| filter d.is_baseline = true
and ${org_filter_predicate}
and ${project_filter_predicate}
and ${target_filter_predicate}
and ${ttype_filter_predicate}
and ${scanner_filter_predicate}
and ${pipeline_filter_predicate}
and ${severity_filter_predicate}
and ${exempted_filter_predicate}
and d.detected >= cast(${start_time} as timestamp) and d.detected <= cast(${end_time} as timestamp)
| select { date_trunc("week", d.detected) as wk, count() as new_detections }
| group_by wk
)
find wk_scans
| left join wk_det wd on wd.wk = wk_scans.wk
| select { wk_scans.wk as week, wk_scans.scans as scans, wd.new_detections as new_detections }
| order_by week asc
| limit 200

find view "view:sto:all_baseline_issue_summary" a
| join view "view:sto:hierarchy_lookup" h_l on h_l.parent_unique_id = a.parent_unique_id and h_l.account_identifier = a.account_identifier
| left join view "view:sto:account_product" p on p.id = a.product_id and p.account_identifier = a.account_identifier
| filter a.status = "Active"
and a.last_modified >= cast(${start_time} as timestamp) and a.last_modified <= cast(${end_time} as timestamp)
and ${org_filter_predicate}
and ${project_filter_predicate}
and ${scanner_filter_predicate}
and ${severity_filter_predicate}
and ${exempted_filter_predicate}
| select {
p.pretty_name as scanner,
a.severity_code as severity,
distinct_count(a.issue_id) as issues
}
| group_by p.pretty_name, a.severity_code
| limit 500

find view "view:sto:detection" d
| join view "view:sto:hierarchy_lookup" h_l on h_l.parent_unique_id = d.parent_unique_id and h_l.account_identifier = d.account_identifier
| left join view "view:sto:account_product" p on p.id = d.product_id and p.account_identifier = d.account_identifier
| left join view "view:sto:target" t on t.id = d.target_id
| join view "view:sto:issue" i on i.internal_id = d.issue_internal_id
| filter d.is_baseline = true
and ${org_filter_predicate}
and ${project_filter_predicate}
and ${target_filter_predicate}
and ${ttype_filter_predicate}
and ${scanner_filter_predicate}
and ${pipeline_filter_predicate}
and ${severity_filter_predicate}
and ${exempted_filter_predicate}
and d.remediated is null
and d.last_scanned >= cast(${start_time} as timestamp) and d.last_scanned <= cast(${end_time} as timestamp)
| select {
i.type as issue_type,
d.severity_code as severity,
(case
when d.severity_code = "Critical" then 5
when d.severity_code = "High" then 4
when d.severity_code = "Medium" then 3
when d.severity_code = "Low" then 2
when d.severity_code = "Info" then 1
else 0
end) as severity_order,
count() as findings
}
| group_by i.type, d.severity_code, severity_order
| order_by severity_order desc
| limit 500

find view "view:sto:all_baseline_issue_summary" a
| join view "view:sto:hierarchy_lookup" h_l on h_l.parent_unique_id = a.parent_unique_id and h_l.account_identifier = a.account_identifier
| left join view "view:sto:account_product" p on p.id = a.product_id and p.account_identifier = a.account_identifier
| filter a.status = "Active"
and a.last_modified >= cast(${start_time} as timestamp) and a.last_modified <= cast(${end_time} as timestamp)
