with open_ch as (
find view "view:sto:detection" d
| join view "view:sto:hierarchy_lookup" h_l on h_l.parent_unique_id = d.parent_unique_id and h_l.account_identifier = d.account_identifier
| left join view "view:sto:account_product" p on p.id = d.product_id and p.account_identifier = d.account_identifier
