| join view "view:sto:issue" i on i.internal_id = d.issue_internal_id
| filter d.is_baseline = true
and ${org_filter_predicate}
and ${project_filter_predicate}
and ${target_filter_predicate}
and ${ttype_filter_predicate}
and ${scanner_filter_predicate}
and ${pipeline_filter_predicate}
and ${severity_filter_predicate}
and ${exempted_filter_predicate}
and d.remediated is null
and d.last_scanned >= cast(${start_time} as timestamp) and d.last_scanned <= cast(${end_time} as timestamp) and (d.severity_code = "Critical" or d.severity_code = "High")
| select {
h_l.org_identifier as org,
h_l.project_identifier as project,
t.name as target,
i.title as issue,
d.severity_code as severity,
p.pretty_name as scanner,
d.detected as first_detected,
d.last_scanned as last_scanned,
date_diff(d.detected, now(), "second") as age,
avg(date_diff(d.detected, now(), "second")) over () as avg_age
}
)
find open_ch
| filter open_ch.age > open_ch.avg_age
| select { open_ch.org as org, open_ch.project as project, open_ch.target as target, open_ch.issue as issue,
open_ch.severity as severity, open_ch.scanner as scanner, open_ch.first_detected as first_detected,
open_ch.last_scanned as last_scanned, open_ch.age as age, round(open_ch.age * 1.0 / open_ch.avg_age, 2) as x_avg_age }
| order_by age desc
| limit 200

